package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ClassNameIdResolver._idFrom
 */
public class ClassNameIdResolver__idFrom_TriageGen1Test {

    private TypeFactory typeFactory;
    private TestableClassNameIdResolver resolver;

    // Subclass to expose protected method and handle _baseType dependency
    private static class TestableClassNameIdResolver extends ClassNameIdResolver {
        private JavaType mockBaseType;

        public TestableClassNameIdResolver(JavaType baseType, TypeFactory typeFactory) {
            super(baseType, typeFactory);
            this.mockBaseType = baseType;
        }

        public void setMockBaseType(JavaType baseType) {
            this.mockBaseType = baseType;
        }

        @Override
        protected String _idFrom(Object value, Class<?> cls, TypeFactory typeFactory) {
            // The original code relies on a field _baseType which is not explicitly 
            // passed but used in the logic. We must ensure the field exists or 
            // simulate the logic if we were mocking. 
            // Since we are testing the actual method, we rely on the super constructor.
            return super._idFrom(value, cls, typeFactory);
        }

        // We need to override the field access if possible, but since it's protected/final 
        // in the real class, we assume the constructor sets it correctly.
        // For the sake of this test, we assume the baseType passed to constructor 
        // is the one used by the logic.
    }

    // Mocking ClassUtil behavior via actual classes where possible
    // Since ClassUtil is an internal Jackson utility, we use standard Java types 
    // to trigger the branches.

    enum TestEnum { A, B }
    static class EnumSubclass extends TestEnum {}
    static class InnerClass { static class Nested {} }

    @Before
    public void setUp() {
        ObjectMapper mapper = new ObjectMapper();
        typeFactory = mapper.getTypeFactory();
        JavaType baseType = typeFactory.constructType(Object.class);
        resolver = new TestableClassNameIdResolver(baseType, typeFactory);
    }

    @Test
    public void testStandardClass() {
        String result = invokeIdFrom("test", String.class, typeFactory);
        assertEquals("java.lang.String", result);
    }

    @Test
    public void testEnumSubclass() {
        // If cls is a subclass of Enum but not an Enum itself, it gets superclass
        String result = invokeIdFrom(TestEnum.A, EnumSubclass.class, typeFactory);
        assertEquals("TestEnum", result); 
        // Note: depending on how Class.getName() works in the test env, 
        // it might be the fully qualified name.
    }

    @Test
    public void testEnumDirect() {
        String result = invokeIdFrom(TestEnum.A, TestEnum.class, typeFactory);
        assertEquals("TestEnum", result);
    }

    @Test
    public void testEnumSet() {
        EnumSet<TestEnum> set = EnumSet.of(TestEnum.A);
        // This triggers the java.util + EnumSet branch
        String result = invokeIdFrom(set, EnumSet.class, typeFactory);
        // Result format: java.util.EnumSet[TestEnum] (canonical)
        // The exact string depends on typeFactory.constructCollectionType(...).toCanonical()
        assertEquals("java.util.EnumSet[TestEnum]", result);
    }

    @Test
    public void testEnumMap() {
        EnumMap<TestEnum, Object> map = new EnumMap<>(TestEnum.class);
        map.put(TestEnum.A, "val");
        String result = invokeIdFrom(map, EnumMap.class, typeFactory);
        // Result format: java.util.EnumMap[TestEnum,java.lang.Object]
        assertEquals("java.util.EnumMap[TestEnum,java.lang.Object]", result);
    }

    @Test
    public void testArraysAsList() {
        List<String> list = Arrays.asList("a", "b");
        // Arrays.asList returns an internal class like java.util.Arrays$ArrayList
        String result = invokeIdFrom(list, list.getClass(), typeFactory);
        assertEquals("java.util.ArrayList", result);
    }

    @Test
    public void testCollectionsWrapper() {
        List<String> list = Collections.singletonList("a");
        // Collections.singletonList returns java.util.Collections$SingletonList
        String result = invokeIdFrom(list, list.getClass(), typeFactory);
        assertEquals("java.util.ArrayList", result);
    }

    @Test
    public void testInnerClassLogic() {
        // This tests the str.indexOf('$') >= 0 branch
        // To trigger the 'cls = _baseType.getRawClass()' branch:
        // 1. cls must be an inner class (contains $)
        // 2. ClassUtil.getOuterClass(cls) != null
        // 3. ClassUtil.getOuterClass(staticType) == null (where staticType is _baseType.getRawClass())

        JavaType baseType = typeFactory.constructType(String.class); // String has no outer class
        resolver = new TestableClassNameIdResolver(baseType, typeFactory);

        String result = invokeIdFrom(new InnerClass.Nested(), InnerClass.Nested.class, typeFactory);
        // Since InnerClass.Nested is an inner class, and baseType (String) has no outer class,
        // it should fallback to the baseType's name.
        assertEquals("java.lang.String", result);
    }

    /**
     * Helper to call the protected method via reflection or the testable subclass
     */
    private String invokeIdFrom(Object value, Class<?> cls, TypeFactory tf) {
        try {
            java.lang.reflect.Method method = ClassNameIdResolver.class.getDeclaredMethod(
                    "_idFrom", Object.class, Class.class, TypeFactory.class);
            method.setAccessible(true);
            return (String) method.invoke(resolver, value, cls, tf);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
